//! Per-character parity of `Console::render_str` highlighting with Python
//! Rich 15, using `tests/fixtures/highlight_repr.golden` (generated by
//! `scripts/gen_highlight_golden.py`).

use fast_rich::highlighter::ReprHighlighter;
use fast_rich::style::{Color, Style};
use fast_rich::text::Text;
use fast_rich::Console;

const GOLDEN: &str = include_str!("fixtures/highlight_repr.golden");

struct Case {
    input: String,
    markup: bool,
    expected: Vec<(usize, usize, String)>,
}

fn decode_hex(hex: &str) -> String {
    if hex == "-" {
        return String::new();
    }
    let bytes: Vec<u8> = (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("hex"))
        .collect();
    String::from_utf8(bytes).expect("utf-8")
}

fn parse_golden() -> Vec<Case> {
    let mut cases: Vec<Case> = Vec::new();
    for line in GOLDEN.lines() {
        let mut parts = line.split(' ');
        match parts.next() {
            Some("I") => cases.push(Case {
                input: decode_hex(parts.next().unwrap()),
                markup: parts.next() == Some("m"),
                expected: Vec::new(),
            }),
            Some("R") => {
                let start = parts.next().unwrap().parse().unwrap();
                let end = parts.next().unwrap().parse().unwrap();
                let desc = parts.next().unwrap().to_string();
                cases.last_mut().unwrap().expected.push((start, end, desc));
            }
            _ => {}
        }
    }
    cases
}

/// `BrightGreen` -> `bright_green`, matching Rich's color names.
fn color_name(color: Color) -> String {
    if color == Color::Default {
        return String::new();
    }
    let debug = format!("{color:?}");
    let mut out = String::new();
    for (i, c) in debug.chars().enumerate() {
        if c.is_ascii_uppercase() {
            if i > 0 {
                out.push('_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

fn describe(style: &Style) -> String {
    let color = style.foreground.map(color_name).unwrap_or_default();
    let mut flags = String::new();
    for (flag, on) in [
        ('b', style.bold),
        ('d', style.dim),
        ('i', style.italic),
        ('u', style.underline),
    ] {
        if on {
            flags.push(flag);
        }
    }
    if color.is_empty() && flags.is_empty() {
        String::new()
    } else {
        format!("{color}:{flags}")
    }
}

/// Per-character runs of non-empty style descriptors (char indices).
fn runs(text: &Text) -> Vec<(usize, usize, String)> {
    let mut out: Vec<(usize, usize, String)> = Vec::new();
    let mut i = 0;
    for span in &text.spans {
        let desc = describe(&span.style.combine(&Style::new()));
        for _ in span.text.chars() {
            match out.last_mut() {
                Some(last) if last.2 == desc && last.1 == i => last.1 = i + 1,
                _ => out.push((i, i + 1, desc.clone())),
            }
            i += 1;
        }
    }
    out.retain(|r| !r.2.is_empty());
    out
}

#[test]
fn highlight_matches_python_rich() {
    let cases = parse_golden();
    assert!(cases.len() > 800, "golden fixture looks truncated");

    let mut failures = Vec::new();
    for case in &cases {
        let console = Console::capture()
            .emoji(false)
            .markup(case.markup)
            .highlighter(ReprHighlighter::new().rich_compatible());
        let text = console.render_str(&case.input);
        if !case.markup {
            assert_eq!(text.plain_text(), case.input, "plain text changed");
        }
        let actual = runs(&text);
        if actual != case.expected {
            failures.push(format!(
                "input: {:?}\n  rich:      {:?}\n  fast-rich: {:?}",
                case.input, case.expected, actual
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from Python Rich:\n{}",
        failures.len(),
        cases.len(),
        failures
            .iter()
            .take(15)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
